// CreateTeam is the resolver for the createTeam field.
func (r *mutationResolver) CreateTeam(ctx context.Context, input model.CreateTeamInput) (*models.Team, error) {
	// Get current user
	user := auth.ForContext(ctx)
	if user == nil {
		return nil, fmt.Errorf("unauthenticated")
	}

	var description string
	if input.Description != nil {
		description = *input.Description
	}

	team := &models.Team{
		Name:        input.Name,
		Description: description,
	}

	// Create team
	if err := r.Repository.CreateTeam(team); err != nil {
		return nil, err
	}

	// Add creator to team
	if err := r.Repository.AddUserToTeam(team.ID, user.ID); err != nil {
		return nil, err
	}

	// Create default board for team
	defaultBoard := &models.Board{
		Name:   "General Board", // Default name
		TeamID: &team.ID,
	}

	if err := r.Repository.CreateBoard(defaultBoard); err != nil {
		// Log error but don't fail team creation? Or fail?
		// For now, let's just log or ignore, or ideally transaction.
		fmt.Printf("Failed to create default board: %v\n", err)
	} else {
		// Link board to team
		team.DefaultBoardID = &defaultBoard.ID // Wait, struct is *string
		// models.Team.DefaultBoardID is *string (UUID)
		// defaultBoard.ID is string
		// So:
		id := defaultBoard.ID
		team.DefaultBoardID = &id
		r.Repository.UpdateTeam(team)
	}

	return team, nil
}

