// Login is the resolver for the login field.
func (r *mutationResolver) Login(ctx context.Context, email string, password string) (*model.AuthPayload, error) {
	// Get user by email
	user, err := r.Repository.GetUserByEmail(email)
	if err != nil {
		return nil, fmt.Errorf("invalid credentials")
	}

	// Verify password hash using Argon2
	if err := models.VerifyPassword(user.Password, password); err != nil {
		return nil, fmt.Errorf("invalid credentials")
	}

	// Generate JWT tokens
	token, refreshToken, err := auth.GenerateToken(user)
	if err != nil {
		return nil, fmt.Errorf("failed to generate token: %v", err)
	}

	return &model.AuthPayload{
		Token:        token,
		RefreshToken: refreshToken,
		User:         user,
	}, nil
}

// Signup is the resolver for the signup field.
func (r *mutationResolver) Signup(ctx context.Context, input model.SignupInput) (*model.AuthPayload, error) {
	// Create user with password (will be hashed by BeforeCreate hook)
	user := &models.User{
		Email:    input.Email,
		Name:     input.Name,
		Username: input.Username,
		Password: input.Password,
	}

	if err := r.Repository.CreateUser(user); err != nil {
		return nil, err
	}

	// Re-fetch user to get all fields populated, especially the ID.
	createdUser, err := r.Repository.GetUserByID(user.ID)
	if err != nil {
		return nil, fmt.Errorf("failed to fetch created user: %v", err)
	}

	// Generate JWT tokens
	token, refreshToken, err := auth.GenerateToken(createdUser)
	if err != nil {
		return nil, fmt.Errorf("failed to generate token: %v", err)
	}

	return &model.AuthPayload{
		Token:        token,
		RefreshToken: refreshToken,
		User:         createdUser,
	}, nil
}

// RefreshToken is the resolver for the refreshToken field.
func (r *mutationResolver) RefreshToken(ctx context.Context, token string) (*model.AuthPayload, error) {
	// Refresh tokens
	newToken, newRefreshToken, err := auth.RefreshToken(token)
	if err != nil {
		return nil, fmt.Errorf("failed to refresh token: %v", err)
	}

	// Get user from token claims
	claims, err := auth.ValidateToken(token)
	if err != nil {
		return nil, fmt.Errorf("invalid refresh token: %v", err)
	}

	// Get user from database
	user, err := r.Repository.GetUserByID(claims.UserID)
	if err != nil {
		return nil, fmt.Errorf("user not found")
	}

	return &model.AuthPayload{
		Token:        newToken,
		RefreshToken: newRefreshToken,
		User:         user,
	}, nil
}

